    ResponseEntity<String> call(HttpMethod method,String path,String token,Object data){HttpHeaders h=new HttpHeaders();if(token!=null)h.set("Authorization",token);h.setContentType(MediaType.APPLICATION_JSON);return http.exchange("http://127.0.0.1:"+port+"/api"+path,method,new HttpEntity<>(data,h),String.class);}
    ResponseEntity<String> get(String path,String token){return call(HttpMethod.GET,path,token,null);}
    JsonNode body(ResponseEntity<String> response)throws Exception{assertNotNull(response.getBody());return json.readTree(response.getBody());}
    String login(long id)throws Exception{return body(call(HttpMethod.POST,"/system/login",null,Map.of("user_id",id,"password","PermissionTest123"))).path("token").asText();}
    Map<String,Object> policy(long id,List<String> roles,Map<String,Boolean> overrides,Map<String,Object> scopes)throws Exception{JsonNode current=body(get("/admin/permissions/users/"+id,admin));return new LinkedHashMap<>(Map.of("mode","CUSTOM","roles",roles,"overrides",overrides,"scopes",scopes,"version",current.path("policy").path("version").asLong(),"revision",current.path("revision").asLong(),"reason","隔离测试权限调整"));}
    void configure(long id,List<String> roles,Map<String,Boolean> overrides,Map<String,Object> scopes)throws Exception{var response=call(HttpMethod.PUT,"/admin/permissions/users/"+id,admin,policy(id,roles,overrides,scopes));assertEquals(200,response.getStatusCode().value(),response.getBody());}
    Map<String,Object> taskScope(String field,List<Long> ids){return Map.of("tasks",Map.of("mode","CUSTOM",field,ids));}
