    @Test void concurrentConfigurationAllowsExactlyOneWriter()throws Exception{var change=policy(90103,List.of("EXPERT"),Map.of(),Map.of());var pool=Executors.newFixedThreadPool(2);try{Future<Integer>a=pool.submit(()->call(HttpMethod.PUT,"/admin/permissions/users/90103",admin,change).getStatusCode().value()),b=pool.submit(()->call(HttpMethod.PUT,"/admin/permissions/users/90103",admin,change).getStatusCode().value());var values=new ArrayList<>(List.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS)));Collections.sort(values);assertEquals(List.of(200,409),values);}finally{pool.shutdownNow();}}
