    Map<String,Object> role(String code,List<String> functions,Map<String,Object> scopes,long version,boolean enabled)throws Exception{return Map.of("code",code,"name","合成角色"+code,"permissions",functions,"scopes",scopes,"version",version,"revision",body(get("/admin/permissions/catalog",admin)).path("revision").asLong(),"enabled",enabled,"reason","隔离角色调整");}
    @Test void rolesCanBeCreatedMergedDisabledButNotDeletedWhileAssigned()throws Exception{
        assertEquals(200,call(HttpMethod.POST,"/admin/permissions/roles",admin,role("TEST_SCOPE",List.of("tasks.read"),Map.of("tasks",Map.of("mode","CUSTOM","items",List.of(3))),0,true)).getStatusCode().value());
        configure(90103,List.of("TEST_SCOPE","FINANCE"),Map.of(),Map.of());assertEquals(3,body(get("/biz/tasks",expert)).size());assertTrue(body(get("/system/access",expert)).path("canFillBudget").asBoolean());
        long rev=body(get("/admin/permissions/catalog",admin)).path("revision").asLong();assertEquals(409,call(HttpMethod.DELETE,"/admin/permissions/roles/TEST_SCOPE?version=1&revision="+rev+"&reason=synthetic",admin,null).getStatusCode().value());
        assertEquals(200,call(HttpMethod.POST,"/admin/permissions/roles",admin,role("TEST_SCOPE",List.of("tasks.read"),Map.of("tasks",Map.of("mode","ALL")),1,false)).getStatusCode().value());assertEquals(403,get("/biz/tasks",expert).getStatusCode().value());
        configure(90103,List.of("FINANCE"),Map.of(),Map.of());rev=body(get("/admin/permissions/catalog",admin)).path("revision").asLong();assertEquals(200,call(HttpMethod.DELETE,"/admin/permissions/roles/TEST_SCOPE?version=2&revision="+rev+"&reason=synthetic",admin,null).getStatusCode().value());
    }
