    @Test void migrationIsIdempotentAndDoesNotRewriteBusinessData()throws Exception{
        String before=jdbc.queryForList("SELECT task_id,dept_id,current_value,progress,status FROM biz_task ORDER BY task_id").toString();
        for(int i=0;i<2;i++)jdbc.execute((ConnectionCallback<Void>)c->{org.springframework.jdbc.datasource.init.ScriptUtils.executeSqlScript(c,new org.springframework.core.io.FileSystemResource("data/migrations/2026-10-24-permissions-expert-reviews.sql"));return null;});assertEquals(before,jdbc.queryForList("SELECT task_id,dept_id,current_value,progress,status FROM biz_task ORDER BY task_id").toString());assertEquals(5,jdbc.queryForObject("SELECT COUNT(*) FROM sys_user_permission",Integer.class));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM biz_material_submission",Integer.class));
    }
